"""Cantor's diagonal argument: no list can enumerate all {0,1}-sequences."""
from typing import Callable, List

def diagonal_escapee(enum: Callable[[int], Callable[[int], int]], n: int) -> List[int]:
    return [1 - enum(k)(k) for k in range(n)]

def demo() -> None:
    enum = lambda i: (lambda k: (i >> k) & 1)
    d = diagonal_escapee(enum, 10)
    print("Escapee sequence:", d)
    for k in range(10):
        assert d[k] != enum(k)(k)
    print("Differs from s_k in position k for all k -> missing from the list.")

if __name__ == "__main__":
    demo()

"""Enumerating periodic sequences over a finite alphabet by (period, block)."""
from itertools import product
from typing import Callable, Iterator, List, Tuple

def periodic(block: List[int]) -> Callable[[int], int]:
    n = len(block)
    return lambda k: block[k % n]

def enumerate_periodic(alphabet: List[int], max_period: int
                       ) -> Iterator[Tuple[List[int], Callable[[int], int]]]:
    for p in range(1, max_period + 1):
        for b in product(alphabet, repeat=p):
            yield list(b), periodic(list(b))

def demo() -> None:
    for block, seq in enumerate_periodic([0, 1], 2):
        print(block, "->", [seq(k) for k in range(8)])

if __name__ == "__main__":
    demo()

"""The Selberg census: explicit conductor-ordered enumeration of the first 100."""
from dataclasses import dataclass
from typing import List, Tuple

@dataclass(frozen=True)
class SelbergDatum:
    degree: int
    conductor: int
    root_num: int
    root_den: int
    euler_coeffs: Tuple[int, ...] = ()

def trivial_datum(q: int) -> SelbergDatum:
    return SelbergDatum(1, q, 0, 1, ())

def census_by_conductor(n: int) -> List[SelbergDatum]:
    return [trivial_datum(q) for q in range(n)]

def demo() -> None:
    first_hundred = census_by_conductor(100)
    conductors = [d.conductor for d in first_hundred]
    assert len(first_hundred) == 100
    assert len(set(first_hundred)) == 100
    assert conductors == list(range(100))
    print("First 100 by conductor: length 100, distinct, conductors 0..99. OK")

if __name__ == "__main__":
    demo()

