function CensusSlice(N, maxEulerLen):
    ints <- [-N .. N]
    eulerLists <- [ () ]
    for L from 1 to min(N, maxEulerLen):
        eulerLists += all tuples of length L over ints
    out <- []
    for deg in 0..N, cond in 0..N, rn in ints, rd in 0..N, ec in eulerLists:
        out += SelbergDatum(deg, cond, rn, rd, ec)
    return out

