from dataclasses import dataclass
from itertools import product
from typing import List, Tuple

@dataclass(frozen=True)
class SelbergDatum:
    degree: int
    conductor: int
    root_num: int
    root_den: int
    euler_coeffs: Tuple[int, ...] = ()

def census_slice(N: int, max_euler_len: int) -> List[SelbergDatum]:
    """Enumerate the finite N-th census slice (all invariants bounded by N),
    capping Euler-list length at max_euler_len for tractability."""
    ints = range(-N, N + 1)
    euler_lists: List[Tuple[int, ...]] = [()]
    for L in range(1, min(N, max_euler_len) + 1):
        euler_lists.extend(product(ints, repeat=L))
    out: List[SelbergDatum] = []
    for deg in range(N + 1):
        for cond in range(N + 1):
            for rn in ints:
                for rd in range(N + 1):
                    for ec in euler_lists:
                        out.append(SelbergDatum(deg, cond, rn, rd, tuple(ec)))
    return out

