from math import gcd
from typing import Dict

def euler_totient(n: int) -> int:
    """phi(n): the number of Dirichlet characters modulo n (n >= 1)."""
    if n <= 1:
        return 1
    return sum(1 for k in range(1, n + 1) if gcd(k, n) == 1)

def cumulative_character_count(max_modulus: int) -> Dict[int, int]:
    """Running total of Dirichlet characters over moduli 1..max_modulus,
    illustrating that a countable union of finite families is countable."""
    total = 0
    out: Dict[int, int] = {}
    for n in range(1, max_modulus + 1):
        total += euler_totient(n)
        out[n] = total
    return out
